-- Strict first-completion evidence for canonical Binah / Leuviah Days 094-098.
create or replace function hnk_private.validate_day094_scalar_evidence_v1(p jsonb) returns void language plpgsql set search_path='' as $$ declare k text; begin
 if p is null or p='{}'::jsonb or jsonb_typeof(p)<>'object' then raise exception 'day094_evidence_required'; end if;
 for k in select jsonb_object_keys(p) loop if k<>all(array['protocol_completed','return_confirmed','focus_object_prepared','observation_completed','fact_interpretation_separated','water_hidden_properties_not_claimed','energy_transfer_not_claimed','intensity_not_scored','orientation_restored','safety_clear','effect_present','practice_seconds']) then raise exception 'day094_evidence_unknown_field'; end if; end loop;
 if p->'protocol_completed' is distinct from 'true'::jsonb or p->'return_confirmed' is distinct from 'true'::jsonb or p->'focus_object_prepared' is distinct from 'true'::jsonb or p->'observation_completed' is distinct from 'true'::jsonb or p->'fact_interpretation_separated' is distinct from 'true'::jsonb or p->'water_hidden_properties_not_claimed' is distinct from 'true'::jsonb or p->'energy_transfer_not_claimed' is distinct from 'true'::jsonb or p->'intensity_not_scored' is distinct from 'true'::jsonb or p->'orientation_restored' is distinct from 'true'::jsonb or p->'safety_clear' is distinct from 'true'::jsonb then raise exception 'day094_required_flag_missing'; end if;
 if jsonb_typeof(p->'effect_present')<>'boolean' then raise exception 'day094_effect_boolean_required'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'practice_seconds'),false) or (p->>'practice_seconds')::int<1 then raise exception 'day094_practice_required'; end if;
end $$;
create or replace function hnk_private.validate_day095_scalar_evidence_v1(p jsonb) returns void language plpgsql set search_path='' as $$ declare k text; begin
 if p is null or p='{}'::jsonb or jsonb_typeof(p)<>'object' then raise exception 'day095_evidence_required'; end if;
 for k in select jsonb_object_keys(p) loop if k<>all(array['protocol_completed','return_confirmed','melancholy_reviewed','self_pity_reviewed','jealousy_reviewed','resentment_reviewed','mood_instability_reviewed','memory_not_forced','diagnosis_not_claimed','moral_sentence_not_claimed','safe_repair_not_forced','vault_saved','orientation_restored','safety_clear','categories_reviewed','total_examples_count']) then raise exception 'day095_evidence_unknown_field'; end if; end loop;
 if p->'protocol_completed' is distinct from 'true'::jsonb or p->'return_confirmed' is distinct from 'true'::jsonb or p->'melancholy_reviewed' is distinct from 'true'::jsonb or p->'self_pity_reviewed' is distinct from 'true'::jsonb or p->'jealousy_reviewed' is distinct from 'true'::jsonb or p->'resentment_reviewed' is distinct from 'true'::jsonb or p->'mood_instability_reviewed' is distinct from 'true'::jsonb or p->'memory_not_forced' is distinct from 'true'::jsonb or p->'diagnosis_not_claimed' is distinct from 'true'::jsonb or p->'moral_sentence_not_claimed' is distinct from 'true'::jsonb or p->'safe_repair_not_forced' is distinct from 'true'::jsonb or p->'vault_saved' is distinct from 'true'::jsonb or p->'orientation_restored' is distinct from 'true'::jsonb or p->'safety_clear' is distinct from 'true'::jsonb then raise exception 'day095_required_flag_missing'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'categories_reviewed'),false) or (p->>'categories_reviewed')::int<>5 or not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'total_examples_count'),false) then raise exception 'day095_counts_invalid'; end if;
end $$;
